apply:
cat > /usr/local/bin/tuxthrottle-irq-rt <<'SH'
#!/usr/bin/env bash
# Real-time priority for GPU + NVMe threaded IRQ handlers (TuxThrottle).
grep -qw threadirqs /proc/cmdline || { echo 'threadirqs not on cmdline - no-op'; exit 0; }
set_rt() {
  local pat=$1 prio=$2 f pid name
  for f in /proc/[0-9]*/comm; do
    read -r name < "$f" 2>/dev/null || continue
    [[ $name =~ $pat ]] || continue
    pid=${f%/comm}; pid=${pid##*/}
    chrt -f -p "$prio" "$pid" 2>/dev/null && echo "rt fifo:$prio  $name ($pid)"
  done
}
set_rt '^irq/[0-9]+-(amdgpu|nvidia)' 50
set_rt '^irq/[0-9]+-nvme' 45
SH
